5	export const cartGet = () => {
6	  try { return JSON.parse(localStorage.getItem(KEY) ?? '[]'); } catch { return []; }
7	};
8	
9	export const cartAdd = (produto, restaurante) => {
10	  const cart = cartGet();
11	  const temPromo = produto.tags?.includes('promo') && produto.preco_promo != null;
12	  const preco = temPromo ? Number(produto.preco_promo) : Number(produto.price);
13	  const key = `${restaurante.id}:${produto.id}`;
14	  const idx = cart.findIndex((i) => i._key === key);
15	  if (idx >= 0) {
16	    cart[idx].qty += 1;
17	  } else {
18	    cart.push({
19	      _key: key,
20	      produto_id: produto.id,
21	      name: produto.name,
22	      price: preco,
23	      image_url: produto.image_url ?? null,
24	      qty: 1,
25	      restaurante_id: restaurante.id,
26	      restaurante_slug: restaurante.slug,
27	      restaurante_nome: restaurante.name,
28	      restaurante_frete: parseFloat(restaurante.frete_motoboy ?? 0),
29	    });
30	  }
31	  localStorage.setItem(KEY, JSON.stringify(cart));
32	  return cart;
33	};
34	
35	export const cartRemoveOne = (key) => {
36	  const cart = cartGet();
37	  const idx = cart.findIndex((i) => i._key === key);
38	  if (idx < 0) return cart;
39	  if (cart[idx].qty > 1) cart[idx].qty -= 1;
40	  else cart.splice(idx, 1);
41	  localStorage.setItem(KEY, JSON.stringify(cart));
42	  return cart;
43	};
44	
45	export const cartRemoveAll = (key) => {
46	  const cart = cartGet().filter((i) => i._key !== key);
47	  localStorage.setItem(KEY, JSON.stringify(cart));
48	  return cart;
49	};
50	
51	export const cartClear = () => localStorage.removeItem(KEY);
